begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('50000000-0000-4000-8000-000000000001','review-owner@example.test','{}'),('50000000-0000-4000-8000-000000000002','review-other@example.test','{}');
update profiles set is_active=true where id in('50000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000002');
insert into user_roles(user_id,role) values('50000000-0000-4000-8000-000000000001','STAFF'),('50000000-0000-4000-8000-000000000002','STAFF') on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at) values('50100000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001',now(),now()),('50100000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000002',now(),now());
insert into clients(id,first_name,last_name,full_name,primary_phone,primary_email,preferred_channel) values('50200000-0000-4000-8000-000000000001','Review','Client','Review Client','+12025550195','review-client@example.test','EMAIL');
insert into pets(id,client_id,name,species) values('50300000-0000-4000-8000-000000000001','50200000-0000-4000-8000-000000000001','Review Dog','Dog');
create temp table review_fixture(key text primary key,value jsonb);grant all on review_fixture to authenticated;
select ok(not has_table_privilege('authenticated','appointment_next_visit_reviews','SELECT'),'Browser cannot read private reviewed requests');
select ok(not has_table_privilege('service_role','appointment_next_visit_reviews','INSERT'),'Service cannot manufacture reviewed requests');
select ok(not has_table_privilege('authenticated','appointment_next_visit_review_cancellations','INSERT'),'Browser cannot forge cancellations');
select ok(not has_function_privilege('anon','prepare_next_visit_review(uuid,uuid,text,jsonb)','EXECUTE'),'Anonymous preparation denied');
select ok(not has_function_privilege('authenticated','guard_next_visit_review(uuid,uuid,text,jsonb)','EXECUTE'),'Canonical guard private');
select ok(not has_function_privilege('authenticated','next_visit_review_session()','EXECUTE'),'Session helper private');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"50100000-0000-4000-8000-000000000001"}',true);
insert into review_fixture select 'source',to_jsonb(save_appointment(auth.uid(),null,null,'50200000-0000-4000-8000-000000000001','50300000-0000-4000-8000-000000000001','2033-01-01T16:00:00Z',30,'Review source','CONFIRMED','50000000-0000-4000-8000-000000000001','clinic','Synthetic',0,0,null,'Synthetic','{}'));
insert into review_fixture select 'complete-request',jsonb_build_object('id',value->>'id','expected_version',1) from review_fixture where key='source';
insert into review_fixture select 'prepared',prepare_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000001','complete',(select value from review_fixture where key='complete-request'));
select is((select value->>'state' from review_fixture where key='prepared'),'prepared','Review preparation saves exact request without completing');
select is((select value->>'request' from review_fixture where key='prepared'),(select value::text from review_fixture where key='complete-request'),'Exact request is frozen on server');
select is(read_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000001'),(select value from review_fixture where key='prepared'),'Reload restores exact review');
select is(prepare_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000001','complete',(select value from review_fixture where key='complete-request')),(select value from review_fixture where key='prepared'),'Repeated preparation is idempotent');
select throws_ok($$select prepare_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000001','complete',jsonb_set((select value from review_fixture where key='complete-request'),'{expected_version}','2'))$$,'23505',null,'Request cannot change under UUID');
select throws_ok($$select prepare_next_visit_review('50000000-0000-4000-8000-000000000002',gen_random_uuid(),'complete',(select value from review_fixture where key='complete-request'))$$,'42501',null,'Session actor required');
insert into review_fixture select 'complete-receipt',execute_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000001');
select is((select value#>>'{appointment,status}' from review_fixture where key='complete-receipt'),'COMPLETED','Prepared completion commits canonical visit');
select is(execute_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000001'),(select value from review_fixture where key='complete-receipt'),'Execute retry returns exact committed receipt');
select is(read_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000001')->>'state','saved','Reload recognizes committed receipt');
select is(cancel_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000001')->>'cancelled','false','Cancel after commit returns receipt instead of erasing completion');
select is(read_appointment_completion((select (value->>'id')::uuid from review_fixture where key='source'),2),(select value->'context' from review_fixture where key='complete-receipt'),'Editor reads exact captured completed version');
select is(read_appointment_completion((select (value->>'id')::uuid from review_fixture where key='source'),1),null::jsonb,'Noncompleted version cannot manufacture occurrence');
insert into review_fixture select 'outcome-request',jsonb_build_object('occurrence_id',value#>>'{context,occurrence,id}','expected_version',0,'values',jsonb_build_object('action','later','note','Synthetic exact later','followup_on',null,'booking',null,'appointment_id',null,'appointment_version',null)) from review_fixture where key='complete-receipt';
select lives_ok($$select prepare_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000002','decide',(select value from review_fixture where key='outcome-request'))$$,'Decision can be prepared privately');
select is(cancel_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000002')->>'cancelled','true','Uncommitted review can be explicitly cancelled');
select is(read_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000002')->>'state','cancelled','Cancelled review preserves request history');
select throws_ok($$select execute_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000002')$$,'PT409',null,'Cancelled review cannot execute');
select throws_ok($$select save_next_visit_outcome(auth.uid(),'50400000-0000-4000-8000-000000000002',(select (value->>'occurrence_id')::uuid from review_fixture where key='outcome-request'),0,(select value->'values' from review_fixture where key='outcome-request'))$$,'PT409',null,'Direct canonical call cannot bypass cancellation');
select is(cancel_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000003')->>'cancelled','true','Missing preparation gets serialized cancellation tombstone');
select throws_ok($$select prepare_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000003','decide',(select value from review_fixture where key='outcome-request'))$$,'PT409',null,'Late preparation cannot resurrect released identifier');
select lives_ok($$select prepare_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000004','decide',(select value from review_fixture where key='outcome-request'))$$,'Fresh reviewed later outcome allowed after cancelled action');
insert into review_fixture select 'later-receipt',execute_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000004');
select is((select value#>>'{decision,kind}' from review_fixture where key='later-receipt'),'later','Later is saved without changing completed status');
select is(read_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000004')->'receipt',(select value from review_fixture where key='later-receipt'),'Lost response reload returns original later receipt');
select is(jsonb_array_length(list_patient_next_visits('50300000-0000-4000-8000-000000000001')->'items'),1,'Patient history retains resolved/pending occurrence');
insert into review_fixture values('editor-request','{"id":null,"expected_version":null,"booking":{"mode":"custom","values":{"client_id":"50200000-0000-4000-8000-000000000001","pet_id":"50300000-0000-4000-8000-000000000001","scheduled_at":"2033-01-03T16:00:00Z","duration_minutes":30,"appointment_type":"Synthetic completed editor","assigned_dvm_id":"50000000-0000-4000-8000-000000000001","visit_type":"clinic","address_snapshot":"Synthetic","travel_before_minutes":0,"travel_after_minutes":0,"resource_name":null,"notes":"Synthetic reviewed completion","reminder_offsets":[]}}}');
select lives_ok($$select prepare_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000006','editor',(select value from review_fixture where key='editor-request'))$$,'Custom completed creation can be prepared exactly');
insert into review_fixture select 'editor-receipt',execute_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000006');
select is((select value#>>'{appointment,status}' from review_fixture where key='editor-receipt'),'COMPLETED','Editor creation commits completed status');
select is((select value#>>'{context,occurrence,appointment_version}' from review_fixture where key='editor-receipt'),'1','Fresh completed insert captures exact first version');
select is(execute_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000006'),(select value from review_fixture where key='editor-receipt'),'Lost editor creation reply never creates twice');
select is(read_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000006')->'receipt',(select value from review_fixture where key='editor-receipt'),'Reload restores editor receipt');
insert into review_fixture select 'editor-notes',jsonb_set(jsonb_set(jsonb_set((select value from review_fixture where key='editor-request'),'{id}',value#>'{appointment,id}'),'{expected_version}','1'),'{booking,values,notes}','"Synthetic notes edit"') from review_fixture where key='editor-receipt';
select prepare_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000007','editor',(select value from review_fixture where key='editor-notes'));
insert into review_fixture select 'editor-notes-receipt',execute_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000007');
select is((select value->'context' from review_fixture where key='editor-notes-receipt'),'null'::jsonb,'Already-completed notes edit invents no new occurrence');
select is((select value#>>'{appointment,version}' from review_fixture where key='editor-notes-receipt'),'2','Notes edit saves canonical version');
select ok(not has_function_privilege('authenticated','save_editor_completion(uuid,uuid,jsonb)','EXECUTE'),'Editor save core stays private behind active-session executor');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000002","role":"authenticated","session_id":"50100000-0000-4000-8000-000000000002"}',true);
select throws_ok($$select read_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000001')$$,'42501',null,'Other account cannot restore reviewed clinical request');
select throws_ok($$select execute_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000004')$$,'42501',null,'Other account cannot execute review');
select throws_ok($$select cancel_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000004')$$,'42501',null,'Other account cannot cancel review');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"50100000-0000-4000-8000-000000000002"}',true);
select throws_ok($$select read_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000001')$$,'42501',null,'Session must belong to current actor');
reset role;
select set_config('request.jwt.claims','{}',true);
insert into appointment_next_visit_reviews(id,actor_id,operation,request,prepared_session_id,prepared_at,expires_at) select '50400000-0000-4000-8000-000000000005','50000000-0000-4000-8000-000000000001','decide',value||'{"expected_version":1}','50100000-0000-4000-8000-000000000001',now()-interval '2 days',now()-interval '1 day' from review_fixture where key='outcome-request';
select throws_ok($$update appointment_next_visit_reviews set request='{}' where id='50400000-0000-4000-8000-000000000005'$$,'23514',null,'Reviewed requests immutable even for operator');
select throws_ok($$delete from appointment_next_visit_review_cancellations where id='50400000-0000-4000-8000-000000000003'$$,'23514',null,'Cancellation cannot be erased');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"50100000-0000-4000-8000-000000000001"}',true);
select is(read_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000005')->>'state','expired','Expired review is visible without claiming saved work');
select throws_ok($$select execute_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000005')$$,'PT409',null,'Expiry requires fresh review');
select throws_ok($$select save_next_visit_outcome(auth.uid(),'50400000-0000-4000-8000-000000000005',(select (value->>'occurrence_id')::uuid from review_fixture where key='outcome-request'),1,(select value->'values' from review_fixture where key='outcome-request'))$$,'PT409',null,'Direct canonical call cannot bypass expiry');
reset role;
select set_config('request.jwt.claims','{}',true);
update auth.sessions set not_after=now()-interval '1 minute' where id='50100000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"50100000-0000-4000-8000-000000000001"}',true);
select throws_ok($$select read_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000001')$$,'42501',null,'Ended session cannot restore even a saved request');
select throws_ok($$select execute_next_visit_review(auth.uid(),'50400000-0000-4000-8000-000000000004')$$,'42501',null,'Ended session cannot execute/replay reviewed draft');
select throws_ok($$select cancel_next_visit_review(auth.uid(),gen_random_uuid())$$,'42501',null,'Ended session cannot release reviewed work');
select * from finish();
rollback;
